from itertools import combinations_with_replacement

# For n digits, only the multiset of digits matters for the sum, so try each
# multiset once instead of every number (about 11,000 checks instead of 10 million).
found = []
for n in range(1, 8):
    for combo in combinations_with_replacement(range(10), n):
        total = sum(d ** n for d in combo)
        if len(str(total)) == n and sorted(int(c) for c in str(total)) == list(combo):
            found.append(total)

for n in range(1, 8):
    group = sorted(x for x in found if len(str(x)) == n)
    print(f"{n}-digit ({len(group)}):", ", ".join(map(str, group)) if group else "none")

def check_armstrong(num):
    digits = str(num)
    return sum(int(d) ** len(digits) for d in digits) == num

def find_in_range(start, end):
    return [n for n in range(start, end + 1) if check_armstrong(n)]

def main():
    while True:
        print("\n--- Armstrong Number Program ---")
        print("1. Check if a number is Armstrong")
        print("2. Find Armstrong numbers in range")
        print("3. Exit")

        choice = input("Enter choice (1-3): ")

        if choice == '1':
            num = int(input("Enter number: "))
            if check_armstrong(num):
                print(f"{num} is an Armstrong number!")
            else:
                print(f"{num} is not an Armstrong number.")

        elif choice == '2':
            start = int(input("Enter start: "))
            end = int(input("Enter end: "))
            result = find_in_range(start, end)
            print(f"Armstrong numbers: {result}")

        elif choice == '3':
            print("Goodbye!")
            break

        else:
            print("Invalid choice. Try again.")

# Run the program
if __name__ == "__main__":
    main()
